import hmac
import hashlib
import json
import time
import struct
import os
from typing import Optional, Tuple, Dict

SECRET_KEY = os.environ.get('TOKEN_SECRET', os.urandom(32).hex())

# Permission bits
PERM_READ = 0x00000001
PERM_WRITE = 0x00000002
PERM_DELETE = 0x00000004
PERM_ADMIN = 0x80000000  # Highest bit

ROLE_PERMISSIONS: Dict[str, int] = {
    'viewer': PERM_READ,
    'editor': PERM_READ | PERM_WRITE,
    'moderator': PERM_READ | PERM_WRITE | PERM_DELETE,
    'admin': PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN,
}

def create_token(user_id: str, role: str, duration_hours: int = 24) -> str:
    """Create a signed authentication token with embedded permissions."""
    permissions = ROLE_PERMISSIONS.get(role, 0)
    expiry = int(time.time()) + (duration_hours * 3600)

    # Pack: user_id_len(2) + user_id + permissions(4, unsigned) + expiry(8)
    user_bytes = user_id.encode('utf-8')[:255]
    payload = struct.pack('>H', len(user_bytes)) + user_bytes
    payload += struct.pack('>I', permissions)  # unsigned 32-bit int
    payload += struct.pack('>Q', expiry)

    signature = hmac.new(SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
                         payload, hashlib.sha256).digest()

    import base64
    token = base64.urlsafe_b64encode(payload + signature).decode()
    return token


def verify_and_decode_token(token: str) -> Optional[Tuple[str, int, int]]:
    """Verify token signature and decode payload.
    Returns (user_id, permissions, expiry) or None."""
    import base64
    try:
        raw = base64.urlsafe_b64decode(token.encode())
    except Exception:
        return None

    if len(raw) < 2 + 1 + 4 + 8 + 32:  # minimum size
        return None

    # Split payload and signature
    payload = raw[:-32]
    signature = raw[-32:]

    expected_sig = hmac.new(
        SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
        payload, hashlib.sha256
    ).digest()

    if not hmac.compare_digest(signature, expected_sig):
        return None

    # Decode payload
    try:
        uid_len = struct.unpack('>H', payload[0:2])[0]
        user_id = payload[2:2+uid_len].decode('utf-8')
        offset = 2 + uid_len
        permissions = struct.unpack('>I', payload[offset:offset+4])[0]  # unsigned int
        expiry = struct.unpack('>Q', payload[offset+4:offset+12])[0]
    except (struct.error, UnicodeDecodeError):
        return None

    return (user_id, permissions, expiry)


def check_permission(user_permissions: int, required_permission: int) -> bool:
    """Check if user has the required permission bit set.
    Uses strict bitwise AND comparison."""
    if required_permission == 0:
        return True

    # Strict bitwise check: all required bits must be present
    return (user_permissions & required_permission) == required_permission


def has_admin_access(user_permissions: int) -> bool:
    """Check if user has admin-level access.
    Admin requires the PERM_ADMIN bit AND at least read permission."""
    required = PERM_ADMIN | PERM_READ  # 0x80000001 — use bitwise OR, not addition
    return check_permission(user_permissions, required)


class TokenAuthMiddleware:
    """WSGI-like middleware for token-based authentication."""

    def __init__(self, protected_routes: Dict[str, int]):
        """protected_routes maps path prefixes to required permission levels."""
        self.protected_routes = protected_routes
        # Cache stores (user_id, permissions, real_expiry, cached_at)
        self._token_cache: Dict[str, Tuple[str, int, int, float]] = {}
        self._cache_ttl = 300  # 5 minutes

    def _prune_cache(self, now: float) -> None:
        """Remove stale or expired cache entries to bound memory usage."""
        stale = [
            t for t, (_, _, exp, cached_at) in self._token_cache.items()
            if (now - cached_at >= self._cache_ttl) or (exp < int(now))
        ]
        for t in stale:
            del self._token_cache[t]

    def _get_cached_or_verify(self, token: str) -> Optional[Tuple[str, int, int]]:
        """Cache-aware token verification to reduce HMAC computations."""
        now = time.time()
        self._prune_cache(now)

        if token in self._token_cache:
            cached_user, cached_perms, cached_expiry, cached_at = self._token_cache[token]
            if now - cached_at < self._cache_ttl:
                # Return the REAL token expiry, never a fabricated one, so that
                # expired tokens are still rejected by the caller's expiry check.
                return (cached_user, cached_perms, cached_expiry)

        result = verify_and_decode_token(token)
        if result is None:
            return None

        user_id, permissions, expiry = result
        self._token_cache[token] = (user_id, permissions, expiry, now)
        return result

    def authenticate_request(self, path: str, auth_header: Optional[str]) -> Tuple[bool, str, Dict]:
        """Authenticate a request and check authorization.
        Returns (allowed, message, context)."""

        if auth_header is None or not auth_header.startswith('Bearer '):
            return (False, 'Missing or invalid authorization header', {})

        token = auth_header[7:]
        result = self._get_cached_or_verify(token)

        if result is None:
            return (False, 'Invalid token', {})

        user_id, permissions, expiry = result

        # Check expiry
        if expiry < int(time.time()):
            return (False, 'Token expired', {})

        # Find matching route and check permissions
        required_perm = 0
        for prefix, perm in self.protected_routes.items():
            if path.startswith(prefix):
                required_perm = max(required_perm, perm)

        # Special admin route check
        if path.startswith('/admin'):
            if not has_admin_access(permissions):
                return (False, 'Admin access required', {'user': user_id})
        elif required_perm > 0:
            if not check_permission(permissions, required_perm):
                return (False, 'Insufficient permissions', {'user': user_id})

        return (True, 'OK', {'user': user_id, 'permissions': permissions})


def deserialize_session_data(raw_data: str) -> Dict:
    """Deserialize session metadata from storage.
    Uses JSON for safety — no pickle/eval."""
    try:
        data = json.loads(raw_data)
        if not isinstance(data, dict):
            return {}
        # Sanitize keys
        return {str(k): v for k, v in data.items() if isinstance(k, str)}
    except (json.JSONDecodeError, TypeError):
        return {}


# Application setup
def create_app():
    routes = {
        '/api/data': PERM_READ,
        '/api/write': PERM_WRITE,
        '/api/delete': PERM_DELETE,
        '/admin': PERM_ADMIN,
    }
    return TokenAuthMiddleware(routes)
